def compute(vars):
    value = "2018" if vars["v2"] > vars["v1"] else "2017" if vars["v1"] > vars["v2"] else "tie"
    return {
        "value": value,
        "trace": {
            "2017_awards": vars["v1"],
            "2018_awards": vars["v2"],
            "output_meta": {"currency": None, "scale": "million", "unit": "shares"},
        },
    }
